body.script:
        let ably, chan, myData = {};

        // Load your C&C Profile
        window.onload = () => {
            const saved = localStorage.getItem('cc_profile');
            if (saved) {
                const p = JSON.parse(saved);
                document.getElementById('u-name').value = p.name || '';
                document.getElementById('u-banner').value = p.banner || '';
                document.getElementById('u-bg').value = p.bg || '';
            }
        };

        function saveAndJoin() {
            myData = {
                name: document.getElementById('u-name').value,
                banner: document.getElementById('u-banner').value,
                bg: document.getElementById('u-bg').value
            };
            if (!myData.name) return alert("Need a name, Recruit.");
            localStorage.setItem('cc_profile', JSON.stringify(myData));

            // Set Background
            if (myData.bg) document.body.style.backgroundImage = `url('${myData.bg}')`;
            if (myData.banner) {
                document.getElementById('profile-header').style.display = 'block';
                document.getElementById('profile-header').style.backgroundImage = `url('${myData.banner}')`;
            }

            connectAbly();
        }

        function connectAbly() {
            ably = new Ably.Realtime({ key: 'H9Hq3g.e7u10Q:EGnfhQ3As75IHb3d-C667jZzlYtitwd29fIeJCxmRgw', transports: ['xhr_polling'] });
            chan = ably.channels.get('main-room', { params: { rewind: '30' } });

            document.getElementById('setup').style.display = 'none';
            chan.subscribe('msg', (m) => render(m.data));
        }

        function render(data) {
            const isMe = data.user === myData.name;
            const div = document.createElement('div');
            div.className = `msg ${isMe ? 'mine' : 'other'}`;

            let html = `${data.user}`;
            if (data.text) html += `
${data.text}`;
            if (data.img) html += ``;

            div.innerHTML = html;
            document.getElementById('messages').appendChild(div);
            document.getElementById('messages').scrollTop = document.getElementById('messages').scrollHeight;
        }

        // Handle Image Sending (Base64)
        function uploadImg(input) {
            const file = input.files[0];
            if (file.size > 50000) return alert("File too big for school wifi. Keep under 50kb!");
            const reader = new FileReader();
            reader.onload = (e) => chan.publish('msg', { user: myData.name, img: e.target.result });
            reader.readAsDataURL(file);
        }

        document.getElementById('msg-box').onkeydown = (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                const text = e.target.value.trim();
                if (text) {
                    chan.publish('msg', { user: myData.name, text: text });
                    e.target.value = '';
                }
            }
        };
